def count_palindrome_subarrays(nums):
    n = len(nums)
    count = 0
    dp = [[False]*n for _ in range(n)]
    for i in range(n):
        dp[i][i] = True
        count += 1
    for i in range(n-1):
        if nums[i] == nums[i+1]:
            dp[i][i+1] = True
            count += 1
    for length in range(3, n+1):
        for i in range(n-length+1):
            j = i+length-1
            if nums[i] == nums[j] and dp[i+1][j-1]:
                dp[i][j] = True
                count += 1
    return count

