    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]

    max_left = [float('-inf')] * n
    curr_max = float('-inf')
    for i in range(n):
        for j in range(i + 1):
            curr = prefix[i + 1] - prefix[j]
            if curr > curr_max:
                curr_max = curr
        max_left[i] = curr_max

    max_right = [float('-inf')] * n
    curr_max = float('-inf')
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            curr = prefix[j + 1] - prefix[i]
            if curr > curr_max:
                curr_max = curr
        max_right[i] = curr_max

    best = float('-inf')
    for i in range(n - 1):
        best = max(best, max_left[i] + max_right[i + 1])
    return best

