def subset_max_gcd(nums):
    n = len(nums)
    if n < 2:
        return 0

    def gcd(a, b):
        a = abs(a)
        b = abs(b)
        while b:
            a, b = b, a % b
        return a

    best = 0
    for mask in range(1, 1 << n):
        subset = []
        for i in range(n):
            if mask & (1 << i):
                subset.append(nums[i])
        if len(subset) < 2:
            continue
        g = subset[0]
        for v in subset[1:]:
            g = gcd(g, v)
        if g > best:
            best = g
    return best

