def subset_max_gcd(nums):
    from math import gcd
    n = len(nums)
    if n < 2:
        return 0
    MAX = max(nums)
    freq = [0] * (MAX + 1)
    for num in nums:
        freq[num] += 1
    best = 0
    for g in range(1, MAX + 1):
        count = 0
        for multiple in range(g, MAX + 1, g):
            count += freq[multiple]
        if count >= 2:
            best = g
    return best
